def write(p,o): p.write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def rel(t,target,**kw): return {'type':t,'target':target,**kw}
def entity(o):
    o.setdefault('relationships',[]); o.setdefault('officialLinks',[]); o.setdefault('referenceSources',[]); write(ENT/f"{o['id']}.json",o)
def enrich(eid,target,role,url,label,stype):
    p=ENT/f'{eid}.json'; d=json.loads(p.read_text(encoding='utf-8'))
    if not any(r.get('target')==target for r in d.get('relationships',[])): d.setdefault('relationships',[]).append(rel('references_publication',target,role=role))
    if not any(s.get('url')==url for s in d.get('referenceSources',[])): d.setdefault('referenceSources',[]).append({'label':label,'url':url,'sourceType':stype,'role':'connected_record_source'})
    write(p,d)

